  1	// Drives system Chrome through every library x task and records what a reader and a developer would observe.
  2	// Usage: node probe.mjs [phase ...]   phases: look, empty, a11y, env, perf, dates, sentinels, lightonly   (default: the first five)
  3	// LIBS=chartjs-tuned,echarts-tuned node probe.mjs perf   runs a subset
  4	import { chromium } from 'playwright-core';
  5	import { PNG } from 'pngjs';
  6	import fs from 'node:fs';
  7	import { loadavg } from 'node:os';
  8	
  9	const BASE = 'http://localhost:4173/';
 10	const LIBS = ['chartjs', 'recharts', 'd3', 'echarts', 'highcharts', 'apexcharts', 'plotly', 'nivo', 'mui', 'uplot', 'axylo'];
 11	const only = process.env.LIBS?.split(',') ?? LIBS;
 12	const phases = process.argv.slice(2).length ? process.argv.slice(2) : ['look', 'empty', 'a11y', 'env', 'perf'];
 13	fs.mkdirSync('shots', { recursive: true });
 14	const resultsFile = 'results.json';
 15	const results = fs.existsSync(resultsFile) ? JSON.parse(fs.readFileSync(resultsFile, 'utf8')) : {};
 16	const save = () => fs.writeFileSync(resultsFile, JSON.stringify(results, null, 1));
 17	const sleep = ms => new Promise(r => setTimeout(r, ms));
 18	
 19	const browser = await chromium.launch({ channel: 'chrome', headless: true });
 20	results._env = { chrome: browser.version(), date: new Date().toISOString(), headless: true };
 21	// every invocation is recorded, so a later partial run does not erase when earlier results were taken
 22	(results._runs ??= []).push({ date: results._env.date, chrome: results._env.chrome, phases, libs: only, settleMs: Number(process.env.SETTLE ?? 1800) });
 23	
 24	const SETTLE = Number(process.env.SETTLE ?? 1800);
 25	async function open(ctxOpts, lib, task, extra = '', settle = SETTLE, timeout = 60000, marks = null) {
 26	  const ctx = await browser.newContext({ viewport: { width: 800, height: 520 }, timezoneId: 'UTC', locale: 'en-US', ...ctxOpts });
 27	  const page = await ctx.newPage();
 28	  const logs = [];
 29	  page.on('console', m => { if (['warning', 'error'].includes(m.type())) logs.push(`${m.type()}: ${m.text().slice(0, 300)}`); });
 30	  page.on('pageerror', e => logs.push(`pageerror: ${String(e).slice(0, 300)}`));
 31	  if (marks) { // main-thread accounting from the browser itself, independent of how a library schedules its work
 32	    const cdp = await ctx.newCDPSession(page); await cdp.send('Performance.enable');
 33	    await page.exposeFunction('__mark', async name => { const { metrics } = await cdp.send('Performance.getMetrics'); marks[name] = Object.fromEntries(metrics.map(m => [m.name, m.value])); });
 34	  }
 35	  await page.goto(`${BASE}?lib=${lib}&task=${task}${extra}`);
 36	  let res;
 37	  try { res = await (await page.waitForFunction(() => window.__result, null, { timeout })).jsonValue(); }
 38	  catch { res = { noResultWithinMs: timeout }; }
 39	  if (settle) await sleep(settle);
 40	  return { ctx, page, logs, res };
 41	}
 42	
 43	const domStats = lib => {
 44	  const el = document.getElementById('chart');
 45	  const all = [...el.querySelectorAll('*')];
 46	  const attrs = ['role', 'aria-label', 'aria-labelledby', 'aria-describedby', 'aria-hidden', 'aria-live', 'tabindex', 'aria-roledescription'];
 47	  const marked = all.filter(n => attrs.some(a => n.hasAttribute(a))).slice(0, 40).map(n => {
 48	    const o = { tag: n.tagName.toLowerCase() };
 49	    for (const a of attrs) if (n.hasAttribute(a)) o[a] = n.getAttribute(a).slice(0, 160);
 50	    return o;
 51	  });
 52	  const texts = [...el.querySelectorAll('svg text')].filter(t => t.textContent.trim());
 53	  const sizes = {}, fills = {};
 54	  for (const t of texts) { const cs = getComputedStyle(t); sizes[cs.fontSize] = (sizes[cs.fontSize] ?? 0) + 1; fills[cs.fill] = (fills[cs.fill] ?? 0) + 1; }
 55	  const htmlText = {};
 56	  if (lib === 'axylo') {
 57	    // Axylo draws the marks in SVG and lays out the plot labels in HTML.
 58	    htmlText.htmlTextSizes = {};
 59	    htmlText.htmlTextColors = {};
 60	    for (const t of el.querySelectorAll('.axylo-text > .axylo-label')) {
 61	      if (!t.textContent.trim() || !t.getClientRects().length) continue;
 62	      const { fontSize, color } = getComputedStyle(t);
 63	      htmlText.htmlTextSizes[fontSize] = (htmlText.htmlTextSizes[fontSize] ?? 0) + 1;
 64	      htmlText.htmlTextColors[color] = (htmlText.htmlTextColors[color] ?? 0) + 1;
 65	    }
 66	  }
 67	  const big = el.querySelector('svg, canvas');
 68	  return {
 69	    nodes: all.length, svg: el.querySelectorAll('svg').length, canvas: el.querySelectorAll('canvas').length,
 70	    svgTitle: el.querySelectorAll('svg title').length, svgDesc: el.querySelectorAll('svg desc').length,
 71	    tables: el.querySelectorAll('table').length, markedCount: all.filter(n => attrs.some(a => n.hasAttribute(a))).length, marked,
 72	    canvasFallback: [...el.querySelectorAll('canvas')].map(c => c.textContent.trim().slice(0, 120)),
 73	    svgTextSizes: sizes, svgTextFills: fills, mainWidth: big ? Math.round(big.getBoundingClientRect().width) : null,
 74	    mainHeight: big ? Math.round(big.getBoundingClientRect().height) : null, ...htmlText,
 75	  };
 76	};
 77	
 78	const shot = async (page, name) => { const p = `shots/${name}.png`; await page.locator('#chart').screenshot({ path: p }); return p; };
 79	const diffRatio = (a, b) => {
 80	  const A = PNG.sync.read(a), B = PNG.sync.read(b);
 81	  if (A.width !== B.width || A.height !== B.height) return 1;
 82	  let n = 0;
 83	  for (let i = 0; i < A.data.length; i += 4) if (Math.abs(A.data[i] - B.data[i]) + Math.abs(A.data[i + 1] - B.data[i + 1]) + Math.abs(A.data[i + 2] - B.data[i + 2]) > 30) n++;
 84	  return n / (A.data.length / 4);
 85	};
 86	const bodyLines = page => page.evaluate(() => document.body.innerText.split('\n').map(s => s.trim()).filter(Boolean));
 87	
 88	for (const lib of only) {
 89	  const R = (results[lib] ??= {});
 90	
 91	  if (phases.includes('look')) for (const task of ['trend', 'bars', 'parts', 'dirty']) {
 92	    const { ctx, page, logs, res } = await open({}, lib, task);
 93	    const out = { res, logs };
 94	    if (!res.unsupported) {
 95	      out.dom = await page.evaluate(domStats, lib);
 96	      out.aria = (await page.locator('#chart').ariaSnapshot().catch(e => 'ERR ' + e)).slice(0, 2500);
 97	      await shot(page, `${task}-${lib}`);
 98	    }
 99	    R[task] = out; save(); await ctx.close();
100	    console.log(lib, task, JSON.stringify(res).slice(0, 120), logs.length ? `logs:${logs.length}` : '');
101	  }
102	
103	  if (phases.includes('empty')) {
104	    // the query returned no rows: what does the reader see, and what does assistive technology get?
105	    const { ctx, page, logs, res } = await open({}, lib, 'empty');
106	    R.empty = { res, logs: logs.slice(0, 4), text: (await bodyLines(page)).filter(l => !['before', 'after'].includes(l)).slice(0, 12),
107	      aria: (await page.locator('#chart').ariaSnapshot().catch(e => 'ERR ' + e)).slice(0, 600) };
108	    await shot(page, `empty-${lib}`); await ctx.close(); save();
109	    console.log(lib, 'empty', JSON.stringify(R.empty.text).slice(0, 160), logs.length ? `logs:${logs.length}` : '');
110	  }
111	
112	  if (phases.includes('dates')) {
113	    // the same daily series given as instants (task trend) and as calendar-date strings (task dates), read in three zones
114	    R.dates = {};
115	    for (const task of ['trend', 'dates']) for (const [tz, tag] of [['UTC', 'utc'], ['America/Los_Angeles', 'la'], ['Asia/Kolkata', 'kolkata']]) {
116	      const o = await open({ timezoneId: tz }, lib, task);
117	      const rec = { res: o.res.error ? { error: o.res.error.slice(0, 160) } : o.res.unsupported ? 'unsupported' : 'ok' };
118	      if (rec.res === 'ok') {
119	        const b0 = await bodyLines(o.page);
120	        const box = await o.page.locator('#chart').boundingBox();
121	        await o.page.mouse.move(box.x + box.width * 0.3, box.y + box.height * 0.5);
122	        await o.page.mouse.move(box.x + box.width * 0.5, box.y + box.height * 0.45, { steps: 8 });
123	        await sleep(500);
124	        rec.hoverText = (await bodyLines(o.page)).filter(l => !b0.includes(l)).slice(0, 8);
125	        // canvas tooltips are invisible to text capture: ask Chart.js for the tooltip it would show for one known datum (index 54 = 2026-02-24)
126	        if (lib === 'chartjs') rec.tooltipForIndex54 = await o.page.evaluate(() => { const c = window.__handle.chart; c.tooltip.setActiveElements([{ datasetIndex: 0, index: 54 }], { x: 0, y: 0 }); c.update(); return { title: c.tooltip.title, body: c.tooltip.body.map(b => b.lines).flat() }; });
127	        // Read the visible Axylo heading separately so the table can retain its time zone.
128	        if (lib === 'axylo') rec.readoutTitle = (await o.page.locator('#chart .axylo-tooltip-title:visible').allTextContents())[0] ?? null;
129	        await shot(o.page, `${task === 'dates' ? 'datestr' : 'instant'}-${tag}-${lib}`);
130	      }
131	      (R.dates[task] ??= {})[tag] = rec; await o.ctx.close();
132	    }
133	    save(); console.log(lib, 'dates', JSON.stringify(R.dates).slice(0, 400));
134	  }
135	
136	  if (phases.includes('sentinels')) {
137	    R.sentinels = {};
138	    for (const kind of ['null', 'nan', 'string', 'undefined']) {
139	      const { ctx, page, logs, res } = await open({}, lib, `dirty-${kind}`);
140	      R.sentinels[kind] = { error: res.error ? res.error.split('\n')[0].slice(0, 160) : null, logCount: logs.length, firstLog: logs[0]?.slice(0, 140) ?? null };
141	      await shot(page, `one-${kind}-${lib}`); await ctx.close();
142	    }
143	    save(); console.log(lib, 'sentinels', JSON.stringify(R.sentinels).slice(0, 300));
144	  }
145	
146	  if (phases.includes('lightonly')) {
147	    // a page that declares itself light-only, viewed on a device set to dark: the chart should stay light
148	    const { ctx, page } = await open({ colorScheme: 'dark' }, lib, 'trend', '&scheme=light');
149	    await shot(page, `lightonly-${lib}`); await ctx.close();
150	  }
151	
152	  if (phases.includes('a11y')) {
153	    const { ctx, page } = await open({}, lib, 'trend');
154	    const k = { stops: [] };
155	    await page.focus('#before');
156	    for (let i = 0; i < 40; i++) {
157	      await page.keyboard.press('Tab');
158	      const a = await page.evaluate(() => {
159	        const e = document.activeElement, c = document.getElementById('chart');
160	        if (e.id === 'after') return 'AFTER';
161	        if (!c.contains(e)) return 'OUTSIDE:' + e.tagName;
162	        const r = e.getBoundingClientRect(), cs = getComputedStyle(e);
163	        return { tag: e.tagName.toLowerCase(), role: e.getAttribute('role'), label: (e.getAttribute('aria-label') ?? e.textContent ?? '').trim().slice(0, 120), cls: String(e.className?.baseVal ?? e.className).slice(0, 60), box: [Math.round(r.width), Math.round(r.height)], outline: cs.outlineStyle + ' ' + cs.outlineWidth };
164	      });
165	      if (a === 'AFTER') break;
166	      k.stops.push(a);
167	    }
168	    // arrow-key exploration from the first stop inside the chart
169	    await page.focus('#before'); await page.keyboard.press('Tab');
170	    const before = await bodyLines(page);
171	    const describe = () => page.evaluate(lib => {
172	      const e = document.activeElement;
173	      const live = [...document.querySelectorAll('[aria-live]')].map(n => n.textContent.trim().slice(0, 200)).filter(Boolean);
174	      const value = lib === 'axylo' ? { valueText: e.getAttribute('aria-valuetext') } : {};
175	      return { active: (e.getAttribute?.('aria-label') ?? e.textContent ?? '').trim().slice(0, 160), tag: e.tagName.toLowerCase(), live, ...value };
176	    }, lib);
177	    k.arrows = [];
178	    for (const key of ['ArrowRight', 'ArrowRight', 'ArrowDown', 'Enter']) { await page.keyboard.press(key); await sleep(250); k.arrows.push({ key, ...(await describe()) }); }
179	    const after = await bodyLines(page);
180	    k.newTextAfterKeys = after.filter(l => !before.includes(l)).slice(0, 12);
181	    await shot(page, `kbd-${lib}`);
182	    R.keyboard = k; await ctx.close();
183	
184	    // pointer hover: what does the default tooltip say?
185	    for (const [tz, tag] of [['UTC', 'utc'], ['America/Los_Angeles', 'la']]) {
186	      const o = await open({ timezoneId: tz }, lib, 'trend');
187	      const b0 = await bodyLines(o.page);
188	      const box = await o.page.locator('#chart').boundingBox();
189	      await o.page.mouse.move(box.x + box.width * 0.3, box.y + box.height * 0.5);
190	      await o.page.mouse.move(box.x + box.width * 0.5, box.y + box.height * 0.45, { steps: 8 });
191	      await sleep(500);
192	      const b1 = await bodyLines(o.page);
193	      R[`hover_${tag}`] = { newText: b1.filter(l => !b0.includes(l)).slice(0, 14) };
194	      await shot(o.page, `hover-${tag}-${lib}`);
195	      await o.ctx.close();
196	    }
197	    save(); console.log(lib, 'a11y', k.stops.length, 'tab stops');
198	  }
199	
200	  if (phases.includes('env')) {
201	    // container resize
202	    { const { ctx, page } = await open({}, lib, 'trend');
203	      await page.evaluate(() => { document.getElementById('chart').style.width = '360px'; });
204	      await sleep(900);
205	      R.resize = await page.evaluate(() => { const c = document.getElementById('chart'); return { widestGraphic: Math.max(...[...c.querySelectorAll('svg, canvas')].map(n => Math.round(n.getBoundingClientRect().width))), scrollWidth: c.scrollWidth }; });
206	      await shot(page, `resize-${lib}`); await ctx.close(); }
207	    // born narrow (phone width)
208	    { const { ctx, page } = await open({}, lib, 'trend', '&w=340'); await shot(page, `narrow-${lib}`); await ctx.close(); }
209	    // dark scheme
210	    { const { ctx, page } = await open({ colorScheme: 'dark' }, lib, 'trend'); await shot(page, `dark-${lib}`); await ctx.close(); }
211	    // motion: compare an early frame with the settled frame, with and without prefers-reduced-motion
212	    for (const rm of ['no-preference', 'reduce']) {
213	      const { ctx, page } = await open({ reducedMotion: rm }, lib, 'bars', '', 0);
214	      const early = await page.locator('#chart').screenshot();
215	      await sleep(2500);
216	      const late = await page.locator('#chart').screenshot();
217	      R[`motion_${rm}`] = { earlyVsSettledDiff: +diffRatio(early, late).toFixed(4) };
218	      await ctx.close();
219	    }
220	    save(); console.log(lib, 'env', R.resize, R['motion_no-preference'], R.motion_reduce);
221	  }
222	
223	  if (phases.includes('perf')) {
224	    R.scale = {};
225	    for (const n of [10000, 100000, 1000000]) {
226	      const prev = R.scale[n / 10];
227	      if (prev && (prev.noResultWithinMs || prev.error || prev.toPaintMs > 8000)) { R.scale[n] = { skipped: 'previous size too slow' }; continue; }
228	      const runs = [];
229	      const load1 = [];
230	      for (let i = 0; i < 3; i++) {
231	        const marks = {};
232	        load1.push(loadavg()[0]);
233	        const { ctx, res } = await open({}, lib, 'scale', `&n=${n}`, 0, 45000, marks);
234	        if (marks['create:end']) res.taskMs = 1000 * (marks['create:end'].TaskDuration - marks['create:start'].TaskDuration);
235	        runs.push(res);
236	        await ctx.close();
237	        if (res.noResultWithinMs || res.error) break;
238	      }
239	      const ok = runs.filter(r => r.toPaintMs).map(r => r.toPaintMs).sort((a, b) => a - b);
240	      const task = runs.filter(r => r.taskMs).map(r => r.taskMs).sort((a, b) => a - b);
241	      R.scale[n] = ok.length ? { toPaintMs: +ok[Math.floor(ok.length / 2)].toFixed(1), runs: ok.map(v => +v.toFixed(1)), taskMs: task.length ? +task[Math.floor(task.length / 2)].toFixed(1) : null, taskRuns: task.map(v => +v.toFixed(1)), failedRuns: runs.length - ok.length } : runs[runs.length - 1];
242	      R.scale[n].load1 = load1;
243	      save(); console.log(lib, 'scale', n, JSON.stringify(R.scale[n]).slice(0, 160));
244	    }
245	    { const marks = {}; const load1 = loadavg()[0]; const { ctx, res, logs } = await open({}, lib, 'stream', '', 0, 90000, marks);
246	      if (marks['stream:end']) { const d = k => 1000 * (marks['stream:end'][k] - marks['stream:start'][k]); res.taskMsPerUpdate = d('TaskDuration') / res.frames; res.scriptMsPerUpdate = d('ScriptDuration') / res.frames; res.layoutStyleMsPerUpdate = (d('LayoutDuration') + d('RecalcStyleDuration')) / res.frames; }
247	      for (const key in res) if (typeof res[key] === 'number') res[key] = +res[key].toFixed(2);
248	      R.stream = { ...res, load1, logs: logs.slice(0, 3) }; await ctx.close(); save(); console.log(lib, 'stream', JSON.stringify(R.stream).slice(0, 200)); }
249	  }
250	}
251	save();
252	await browser.close();

     1	import * as data from './data.js';
     2	const mods = import.meta.glob('./libs/*.{js,jsx}');
     3	const q = new URLSearchParams(location.search);
     4	const lib = q.get('lib'), task = q.get('task') ?? 'trend', n = Number(q.get('n') ?? 100000);
     5	const el = document.getElementById('chart');
     6	if (q.get('w')) el.style.width = q.get('w') + 'px';
     7	if (q.get('scheme')) document.documentElement.style.colorScheme = q.get('scheme'); // e.g. a light-only page under a dark OS
     8	const mark = name => window.__mark ? window.__mark(name) : null; // the probe records CDP main-thread metrics at these points
     9	const raf = () => new Promise(r => requestAnimationFrame(() => r()));
    10	window.__result = null;
    11	(async () => {
    12	  const key = Object.keys(mods).find(k => k.startsWith(`./libs/${lib}.`));
    13	  if (!key) { el.textContent = 'Choose a library and task, for example ?lib=axylo&task=trend'; return; }
    14	  try {
    15	    const m = await mods[key]();
    16	    const one = task.startsWith('dirty-') ? task.slice(6) : null;
    17	    const fn = task === 'empty' ? m.trend : one ? m.dirty : m[task];
    18	    if (!fn) { window.__result = { unsupported: true }; el.textContent = `${lib}: ${task} not supported`; return; }
    19	    // "empty": the trend chart when the query returned no rows
    20	    const d = task === 'scale' ? data.scale(n) : task === 'stream' ? data.stream()
    21	      : task === 'empty' ? { ...data.trend, title: 'Daily sessions by channel', t: [], series: data.trend.series.map(s => ({ ...s, values: [] })) }
    22	      : one ? data.dirtyOne(one)
    23	      : data[task];
    24	    await raf();
    25	    await mark('create:start');
    26	    const t0 = performance.now();
    27	    const handle = await fn(el, d);
    28	    const t1 = performance.now();
    29	    await raf(); await raf();
    30	    const t2 = performance.now();
    31	    window.__handle = handle;
    32	    const res = { createMs: t1 - t0, toPaintMs: t2 - t0 };
    33	    if (window.__mark) { await new Promise(r => setTimeout(r, 1600)); await mark('create:end'); } // long enough for entry animations to finish
    34	    if (task === 'stream') {
    35	      // let entry animations settle, then push one point per frame
    36	      await new Promise(r => setTimeout(r, 1500));
    37	      const frames = Number(q.get('frames') ?? 300), push = [], gaps = [];
    38	      await mark('stream:start');
    39	      let last = performance.now();
    40	      for (let i = 0; i < frames; i++) {
    41	        const [x, y] = d.next();
    42	        const a = performance.now(); handle.push(x, y); push.push(performance.now() - a);
    43	        await raf(); const now = performance.now(); gaps.push(now - last); last = now;
    44	      }
    45	      await raf(); await mark('stream:end');
    46	      const pct = (arr, p) => [...arr].sort((a, b) => a - b)[Math.min(arr.length - 1, Math.floor(arr.length * p))];
    47	      Object.assign(res, { pushP50: pct(push, 0.5), pushP95: pct(push, 0.95), frameP50: pct(gaps, 0.5), frameP95: pct(gaps, 0.95), framesOver20ms: gaps.filter(g => g > 20).length, frames });
    48	    }
    49	    window.__result = res;
    50	  } catch (e) { console.error(e); window.__result = { error: String(e?.stack ?? e) }; }
    51	})();
