  5	const el = document.getElementById('chart');
  6	if (q.get('w')) el.style.width = q.get('w') + 'px';
  7	if (q.get('scheme')) document.documentElement.style.colorScheme = q.get('scheme'); // e.g. a light-only page under a dark OS
  8	const mark = name => window.__mark ? window.__mark(name) : null; // the probe records CDP main-thread metrics at these points
  9	const raf = () => new Promise(r => requestAnimationFrame(() => r()));
 10	window.__result = null;
 11	(async () => {
 12	  const key = Object.keys(mods).find(k => k.startsWith(`./libs/${lib}.`));
 13	  if (!key) { el.textContent = 'Choose a library and task, for example ?lib=axylo&task=trend'; return; }
 14	  try {
 15	    const m = await mods[key]();
 16	    const one = task.startsWith('dirty-') ? task.slice(6) : null;
 17	    const fn = task === 'empty' ? m.trend : one ? m.dirty : m[task];
 18	    if (!fn) { window.__result = { unsupported: true }; el.textContent = `${lib}: ${task} not supported`; return; }
 19	    // "empty": the trend chart when the query returned no rows
 20	    const d = task === 'scale' ? data.scale(n) : task === 'stream' ? data.stream()
 21	      : task === 'empty' ? { ...data.trend, title: 'Daily sessions by channel', t: [], series: data.trend.series.map(s => ({ ...s, values: [] })) }
 22	      : one ? data.dirtyOne(one)
 23	      : data[task];
 24	    await raf();
 25	    await mark('create:start');
 26	    const t0 = performance.now();
 27	    const handle = await fn(el, d);
 28	    const t1 = performance.now();
 29	    await raf(); await raf();
 30	    const t2 = performance.now();
 31	    window.__handle = handle;
 32	    const res = { createMs: t1 - t0, toPaintMs: t2 - t0 };
 33	    if (window.__mark) { await new Promise(r => setTimeout(r, 1600)); await mark('create:end'); } // long enough for entry animations to finish
 34	    if (task === 'stream') {
 35	      // let entry animations settle, then push one point per frame
 36	      await new Promise(r => setTimeout(r, 1500));
 37	      const frames = Number(q.get('frames') ?? 300), push = [], gaps = [];
 38	      await mark('stream:start');
 39	      let last = performance.now();
 40	      for (let i = 0; i < frames; i++) {
 41	        const [x, y] = d.next();
 42	        const a = performance.now(); handle.push(x, y); push.push(performance.now() - a);
 43	        await raf(); const now = performance.now(); gaps.push(now - last); last = now;
 44	      }
 45	      await raf(); await mark('stream:end');
 46	      const pct = (arr, p) => [...arr].sort((a, b) => a - b)[Math.min(arr.length - 1, Math.floor(arr.length * p))];
 47	      Object.assign(res, { pushP50: pct(push, 0.5), pushP95: pct(push, 0.95), frameP50: pct(gaps, 0.5), frameP95: pct(gaps, 0.95), framesOver20ms: gaps.filter(g => g > 20).length, frames });
 48	    }
 49	    window.__result = res;
 50	  } catch (e) { console.error(e); window.__result = { error: String(e?.stack ?? e) }; }
 51	})();
