import json, subprocess
from collections import Counter
from pathlib import Path
p='research/harness/results.json'
old=json.loads(subprocess.run(['git','show',':'+p],check=True,capture_output=True,text=True).stdout)
new=json.loads(Path(p).read_text())
changes=[]
def walk(a,b,path=()):
    if type(a) "'!= type(b): changes.append(path); return
    if isinstance(a,dict):
        for k in a.keys() | b.keys():
            if k not in a or k not in b: changes.append(path+(k,))
            else: walk(a[k],b[k],path+(k,))
    elif isinstance(a,list):
        for i,(x,y) in enumerate(zip(a,b)): walk(x,y,path+(str(i),))
        for i in range(min(len(a),len(b)),max(len(a),len(b))): changes.append(path+(str(i),))
    elif a!=b: changes.append(path)
walk(old,new)
groups=Counter('"'.'.join(p[:2]) for p in changes)
print('Every changed results.json path grouped by configuration/field:')
for key,count in sorted(groups.items()): print(key,count)
allowed=lambda p: p==('_env','date') or (p[0]=='_runs' and len(p)==2 and int(p[1])>=len(old['_runs'])) or (len(p)>=2 and p[1] in ('scale','stream'))
